var file_map = map[string]string{

	"animation_generator.baml":        "class GenerateAnimationCodeRequest {\n  animationType AnimationType\n  animationPrompt string @description(\"Visual animation blueprint generated earlier\")\n  durationInFrames int @description(\"Target duration in frames requested for the animation.\")\n  voiceover string? @description(\"Optional narration text for timing alignment\")\n  branding VideoBranding\n}\n\nclass GenerateAnimationCodeResponse {\n  code string @description(\"Typescript code\")\n}\n\nfunction GenerateAnimation(resume: GenerateAnimationCodeRequest, conversation_history: Message[]) -> GenerateAnimationCodeResponse {\n  client CustomOpenAI5\n  prompt #\"\n    You are generating a React animation component for a video slide.\n    ---\n\n    ## CONTEXT\n    A video is composed of multiple slides rendered in sequence.\n    You are generating ONE slide component.\n\n    The component runs inside a managed animation runtime — you do not need to know\n    how it is composed or rendered. Focus only on writing the component itself.\n\n    Your component must follow the rules and use only the components listed below.\n    Any code that violates the rules will be rejected automatically.\n\n    ---\n\n    {{ CodeGeneration() }}\n    {{ CodeGenerationExamples() }}\n    {{ CodeGenerationMustHave() }}\n    {{ FrameDurationRules() }}\n\n    ---\n    ## INPUT\n\n    ## Animation Duration In Frames:\n    {{ resume.durationInFrames }}\n\n    ## ANIMATION BRIEF:\n    {{ resume.animationPrompt }}\n\n    ## Animation type to generate:\n    {{ resume.animationType }}\n\n    {% if resume.voiceover %}\n    ## Voiceover that will be played in this slide:\n    {{ resume.voiceover }}\n    {% endif %}\n\n    {{ BrandGuidelines(resume.branding) }}\n\n    ---\n\n    {% if conversation_history %}\n    ## Conversation History\n    {% for message in conversation_history %}\n    {{ _.role(message.role) }} {{ message.content }}\n    {% endfor %}\n    {% endif %}\n\n    ---\n    {{ ctx.output_format }}\n  \"#\n}",
	"animation_prompt_enhancer.baml":  "class EnhanceAnimationPromptRequest {\n  prompt string\n  branding VideoBranding\n}\n\nclass EnhancedAnimationPrompt {\n  prompt string\n      @description(\"Detailed prompt to generate animation code\")\n  animationIntent string\n      @description(\"Conceptual meaning of the animation used for semantic matching with templates. Describe the idea or transformation being visualized (e.g. 'scattered data merging into one system', 'rapid metric growth', 'automation replacing manual work').\")\n  animationType AnimationType\n      @description(\"Type of animation to use based on storytelling needs.\")\n  categorySearchQuery string\n      @description(\"Semantic search query describing the conceptual animation category, NOT visual style. Example: 'data fragmentation problem', 'centralization of scattered systems', 'growth acceleration', 'workflow automation'.\")\n  durationInFrames int\n      @description(\"Duration of the animation in frames(fps = 30)\")\n}\n\nclass EnhanceAnimationPromptResponse {\n  plan (EnhancedAnimationPrompt | AskUserQuestion) @description(\"Either the enhanced prompt or a followup question for the user\")\n}\n\nfunction EnhanceAnimationPrompt(request: EnhanceAnimationPromptRequest, conversation_history: Message[]) -> EnhanceAnimationPromptResponse {\n  client CustomOpenAI5\n  prompt #\"\n   # Animation Prompt Designer\n\n   You are a motion design planner that converts a short idea into a clear animation blueprint for a React-based video animation system.\n\n   Your job is to enhance the user's idea into a concise animation concept using only the allowed visual mechanisms listed below.\n\n   Do NOT write code.\n   Do NOT describe implementation details.\n\n   ---\n\n   ## Output Rules\n\n   Write exactly ONE paragraph (60–80 words).\n\n   The paragraph must clearly describe:\n\n   • the main visual element\n   • how elements enter the screen\n   • the sequence of motion\n   • the focal point of the composition\n   • how the animation ends or holds\n   • *All timing values are in frames (fps=30)*\n   • Never use decimal values for duration or startAt.\n   • stay within the capabilities implied by the available visual mechanisms\n   • describe motion in natural visual language\n   • do not mention component names unless needed for unusual precision\n\n    {{ CodeGenerationMustHave() }}\n\n    {{ AllComponentsList() }}\n\n    ---\n\n    ## Example Output\n\n    A bold headline appears at the center of the frame, followed by a short supporting line rising gently beneath it.\n    Three quick benefit statements reveal one after another to build momentum, while a single key word updates to sharpen the message.\n    The composition stays centered and easy to read, then settles into a clean hold before fading away. Total duration: 180 frames (6 seconds).\n\n    ---\n\n    ## Animation Type\n\n    Select the animation type that best matches the motion concept.\n\n    {{ AnimationTypes() }}\n\n   ## CLARIFICATION RULE\n\n   If the user prompt is too vague to design a clear animation,\n   ask clarification question instead of generating the animation.\n\n   Only ask a question when:\n   • The animation concept is unclear\n   • The visual transformation cannot be inferred\n   • Multiple animation interpretations are possible\n\n   {{ AskQuestionGuidelines() }}\n\n    ---\n\n    ## Design Thinking\n\n    Before writing the final paragraph, think step-by-step about the animation concept:\n\n    • identify the primary visual element\n    • choose the layout and focal point\n    • decide how elements enter\n    • plan the sequencing of motion\n    • determine how the animation holds or exits\n    • choose an appropriate duration (120–240 frames/4-8s)\n\n    Then write the final paragraph following the Output Rules.\n\n    ---\n\n    ## Input\n\n    User Prompt:\n    {{ request.prompt }}\n\n    Brand Guidelines:\n    {{ BrandGuidelines(request.branding) }}\n    ---\n\n    {% if conversation_history %}\n    ## Conversation History\n    {% for message in conversation_history %}\n    {{ _.role(message.role) }} {{ message.content }}\n    {% endfor %}\n    {% endif %}\n\n    {{ ctx.output_format }}\n  \"#\n}\n",
	"animation_prompt_generator.baml": "class GenerateAnimationPromptRequest {\n  animationType AnimationType\n  currentBeat string @description(\"Narrative intent of the slide that needs a new visual structure\")\n  planSoFar Section[] @description(\"Sections and slides already generated\")\n  voiceover string?\n  branding VideoBranding\n}\n\nclass GenerateAnimationPromptResponse {\n  prompt string @description(\"detailed prompt to generate remotion/react code animation\")\n}\nfunction GenerateAnimationPrompt(resume: GenerateAnimationPromptRequest) -> GenerateAnimationPromptResponse {\n  client CustomOpenAI5\n  prompt #\"\n   You are a motion design director for short-form video.\n\n   You will receive:\n   - The video's narrative goal and tone\n   - A list of slides already generated with their visual structure\n   - The next narrative beat that needs to be communicated\n\n   Your job is to design the animation concept for the next slide.\n   Do not write code. Do not describe implementation details.\n   Avoid repeating visual structures already used in previous slides.\n\n   ## Output Rules\n\n   Write exactly ONE paragraph (60–80 words).\n\n   The paragraph must clearly describe:\n\n   • the main visual element\n   • how elements enter the screen\n   • the sequence of motion\n   • the focal point of the composition\n   • how the animation ends or holds\n   • stay within the capabilities implied by the available visual mechanisms\n   • describe motion in natural visual language\n   • do not mention component names unless needed for unusual precision\n\n\n   {{ AnimationTypes() }}\n\n   {{ AllComponentsList() }}\n\n   {{ CodeGenerationMustHave() }}\n\n    ## Example Output\n\n    A strong headline lands first in the center, with a supporting line rising into place just after it.\n    Three short proof points appear in sequence to create rhythm, while one changing keyword adds emphasis without overwhelming the frame.\n    The slide feels distinct by keeping everything focused on a single central message, then holds long enough to read before easing out.\n\n\n    ## Design Thinking\n\n    Before writing the final paragraph, think step-by-step about the animation concept:\n\n    • identify the primary visual element\n    • choose the layout and focal point\n    • decide how elements enter\n    • plan the sequencing of motion\n    • determine how the animation holds or exits\n\n    Then write the final paragraph following the Output Rules.\n\n    ---\n\n   --------------------------------------------------\n   INPUT\n   --------------------------------------------------\n\n    ## Narrative So Far\n\n    {% for section in resume.planSoFar %}\n      {% if section.slides|length > 0 %}\n    Section: {{ section.name }}\n        {% for slide in section.slides %}\n    - Concept: {{ slide.beatDescription }}\n      Visual Used: {{ slide.selectedTemplateDescription }}\n        {% endfor %}\n      {% endif %}\n    {% endfor %}\n\n    ## Outline/Beat To Visualize\n    Concept outline/beat:\n    {{ resume.currentBeat }}\n\n    Animation type to generate:\n    {{ resume.animationType }}\n\n    {% if resume.voiceover %}\n    Voiceover that will be played in this slide:\n    {{ resume.voiceover }}\n    {% endif %}\n\n    {{ BrandGuidelines(resume.branding) }}\n\n    ---\n    --------------------------------------------------\n\n    {{ ctx.output_format }}\n  \"#\n}\n",
	"clients.baml":                    "// Learn more about clients at https://docs.boundaryml.com/docs/snippets/clients/overview\n\nclient<llm> CustomGeminiFlash {\n  provider google-ai\n  retry_policy Exponential\n  options {\n    model \"gemini-2.0-flash\"\n    api_key env.GOOGLE_API_KEY\n    generationConfig {\n      temperature 0.3\n    }\n  }\n}\n\nclient<llm> CustomClaudeOpus {\n  provider \"anthropic\"\n  retry_policy Exponential\n  options {\n    model \"claude-opus-4-6\"\n    api_key env.ANTHROPIC_API_KEY\n    max_tokens 12000\n    temperature 0.1\n  }\n}\n\nclient<llm> CustomOpenAI {\n  provider \"openai-responses\"\n  retry_policy Exponential\n  options {\n    model \"gpt-5.4\"\n    api_key env.OPENAI_API_KEY\n    //max_completion_tokens 12000\n  }\n}\n\nclient<llm> CustomOpenAI5 {\n  provider \"openai-responses\"\n  retry_policy Exponential\n  options {\n    model \"gpt-5.4\"\n    api_key env.OPENAI_API_KEY\n    //max_completion_tokens 12000\n    reasoning {\n      effort \"medium\"\n    }\n  }\n}\n\n// https://docs.boundaryml.com/docs/snippets/clients/retry\nretry_policy Constant {\n  max_retries 3\n  strategy {\n    type constant_delay\n    delay_ms 200\n  }\n}\n\nretry_policy Exponential {\n  max_retries 2\n  strategy {\n    type exponential_backoff\n    delay_ms 300\n    multiplier 1.5\n    max_delay_ms 10000\n  }\n}",
	"code_generation_examples.baml":   "template_string CodeGenerationExamples() #\"\n## EXAMPLES:\n\n{% raw %}\n### Example 1 — title with sequential reveals\n```tsx\nexport default function RemoteComponent() {\n  return (\n    <SafeArea>\n      <AbsoluteCenter axis=\"both\">\n        <Stack gap={16} align=\"center\">\n          <SlideIn delay={0} duration={20} direction=\"up\">\n            <Text variant=\"display\">Q4 Results</Text>\n          </SlideIn>\n          <FadeIn delay={26} duration={20}>\n            <Text variant=\"subheading\">Revenue up this quarter</Text>\n          </FadeIn>\n        </Stack>\n      </AbsoluteCenter>\n    </SafeArea>\n  );\n}\n```\n\n### Example 2 — two stats side by side\n```tsx\nexport default function RemoteComponent() {\n  return (\n    <SafeArea>\n      <AbsoluteCenter axis=\"both\">\n        <Row gap={48} align=\"center\">\n          <FadeIn delay={0} duration={20}>\n            <Stack gap={8} align=\"center\">\n              <Counter to={9800} delay={0} duration={60} suffix=\"+\" variant=\"heading\" />\n              <Text variant=\"label\">new users</Text>\n            </Stack>\n          </FadeIn>\n          <FadeIn delay={10} duration={20}>\n            <Stack gap={8} align=\"center\">\n              <Counter to={94} delay={10} duration={60} suffix=\"%\" variant=\"heading\" />\n              <Text variant=\"label\">retention</Text>\n            </Stack>\n          </FadeIn>\n        </Row>\n      </AbsoluteCenter>\n    </SafeArea>\n  );\n}\n```\n\n### Example 3 — staggered list\n```tsx\nexport default function RemoteComponent() {\n  return (\n    <SafeArea>\n      <AbsoluteCenter axis=\"both\">\n        <Stack gap={12} align=\"center\">\n          <SlideIn delay={0} duration={20} direction=\"up\">\n            <Text variant=\"heading\">What we shipped</Text>\n          </SlideIn>\n          <TimelineGate showAfter={26}>\n            <Stagger startAt={26} delayBetween={8}>\n              <SlideIn duration={20} direction=\"up\">\n                <Text variant=\"body\">Faster build times</Text>\n              </SlideIn>\n              <SlideIn duration={20} direction=\"up\">\n                <Text variant=\"body\">Improved test coverage</Text>\n              </SlideIn>\n              <SlideIn duration={20} direction=\"up\">\n                <Text variant=\"body\">Zero downtime deploys</Text>\n              </SlideIn>\n            </Stagger>\n          </TimelineGate>\n        </Stack>\n      </AbsoluteCenter>\n    </SafeArea>\n  );\n}\n```\n\n### Example 4 — word cycle resolving to final word\n```tsx\nexport default function RemoteComponent() {\n  return (\n    <SafeArea>\n      <AbsoluteCenter axis=\"both\">\n        <Stack gap={16} align=\"center\" style={{ maxWidth: 700 }}>\n          <FadeIn delay={0} duration={20}>\n            <Text variant=\"subheading\">We protect your</Text>\n          </FadeIn>\n          <TimelineGate showAfter={26} hideAfter={130}>\n            <WordCycle\n              words={[\"layouts\", \"spacing\", \"colors\", \"trust\"]}\n              holdDuration={18}\n              transitionDuration={10}\n              transition=\"fadeSwap\"\n              variant=\"display\"\n            />\n          </TimelineGate>\n          <TimelineGate showAfter={136}>\n            <ScaleIn delay={0} duration={20} origin=\"center\">\n              <Text variant=\"display\">trust</Text>\n            </ScaleIn>\n          </TimelineGate>\n        </Stack>\n      </AbsoluteCenter>\n    </SafeArea>\n  );\n}\n```\n{% endraw %}\n\"#",
	"code_generation_prompt.baml":     "template_string CodeGeneration() #\"\n## FRAME CONTRACT:\n\n- Your component runs inside a managed animation runtime.\n- It receives no props.\n- Export as: export default function RemoteComponent() { ... }\n- Remotion and all animation libraries are provided by the runtime — never import them.\n\n## Available CANVAS size:\n1920px × 1080px (web)\n\n## LAYOUT\n\n### SafeArea\nOutermost content wrapper that applies safe area insets from the active aspect preset\nProps:\n\n### Stack\nVertical flex layout with spacing token values for gap\nProps:\n- gap: number (optional)\n- align: string (optional)\n- justify: string (optional)\n\n### Row\nHorizontal flex layout with spacing token values for gap\nProps:\n- gap: number (optional)\n- align: string (optional)\n- justify: string (optional)\n\n### AbsoluteCenter\nCenters child absolutely within nearest positioned parent\nProps:\n- axis: enum(x|y|both) (optional)\n\n\n## ANIMATION PRIMITIVES\n\n### FadeIn\nFade-in entrance animation (opacity 0 to 1)\nProps:\n- delay: number (optional)\n- duration: number (optional)\n\n### FadeOut\nFade-out exit animation (opacity 1 to 0)\nProps:\n- delay: number (optional)\n- duration: number (optional)\n\n### SlideIn\nSlide-in entrance with translation and fade\nProps:\n- delay: number (optional)\n- duration: number (optional)\n- direction: enum(up|down|left|right) (optional)\n- distance: number (optional)\n\n### SlideOut\nSlide-out exit with translation and fade\nProps:\n- delay: number (optional)\n- duration: number (optional)\n- direction: enum(up|down|left|right) (optional)\n- distance: number (optional)\n\n### ScaleIn\nScale-in entrance animation (scale 0 to 1)\nProps:\n- delay: number (optional)\n- duration: number (optional)\n- origin: enum(center|top|bottom|left|right) (optional)\n\n### ScaleOut\nScale-out exit animation (scale 1 to 0)\nProps:\n- delay: number (optional)\n- duration: number (optional)\n- origin: enum(center|top|bottom|left|right) (optional)\n\n### Stagger\nStaggers children animations with increasing delay offsets\nProps:\n- startAt: number (optional)\n- delayBetween: number (optional)\n\n### TimelineGate\nMounts/unmounts children within a frame window, use instead of JSX conditionals\nProps:\n- showAfter: number (required)\n- hideAfter: number (optional)\n\n\n## CONTENT\n\n### Text\nStatic text element, wrap in FadeIn/SlideIn to animate\nProps:\n- variant: enum(caption|label|body|subheading|heading|display) (optional)\n\n### Counter\nAnimated number counter that tweens between values\nProps:\n- delay: number (optional)\n- duration: number (optional)\n- from: number (optional)\n- to: number (required)\n- format: string (optional)\n- prefix: string (optional)\n- suffix: string (optional)\n- variant: enum(caption|label|body|subheading|heading|display) (optional)\n\n### Typewriter\nProgressively reveals text character by character, word, or line\nProps:\n- delay: number (optional)\n- duration: number (optional)\n- text: string (required)\n- mode: enum(char|word|line) (optional)\n- variant: enum(caption|label|body|subheading|heading|display) (optional)\n\n### WordCycle\nCycles through an array of words with animated transitions\nProps:\n- delay: number (optional)\n- words: array (required)\n- holdDuration: number (optional)\n- transitionDuration: number (optional)\n- transition: enum(flipY|fadeSwap|slideUp) (optional)\n- variant: enum(caption|label|body|subheading|heading|display) (optional)\n\n\n## SCENES\n\n### TitleCard\nPre-built hero title card composition with heading, subheading, and eyebrow\nProps:\n- heading: string (required)\n- subheading: string (optional)\n- eyebrow: string (optional)\n- delay: number (optional)\n\n\n## BRAND\n\n### LogoAsset\nBrand logo from ThemeProvider. Falls back to a placeholder if no logo is configured. Wrap in any animation primitive (FadeIn, SlideIn, ScaleIn etc.) to animate. Width and height define the bounding box; the logo always keeps its aspect ratio.\nProps:\n- width: number (optional)\n- height: number (optional)\n\n\n## SPACING (use these values for gap/padding/margin):\n 4 | 8 | 12 | 16 | 24 | 32 | 48 | 64 | 96\n\n## TYPOGRAPHY variants:\ncaption | label | body | subheading | heading | display — never hardcode font sizes\n\n## TIMING GUIDANCE (fps=30, so 30 frames = 1 second):\n\n- Typical entrance: 15-25 frames\n- Typical exit: 10-15 frames\n- Stagger between items: 6-10 frames\n- Counter animation: 30-60 frames\n- Typewriter per character: 2-3 frames (set duration = text.length * 2)\n- Hold before next section: 10-20 frames\n\"#\n\ntemplate_string CodeGenerationMustHave() #\"\n## ANIMATION QUALITY\n\n- Keep text minimal — one or two key messages per animation, never more than five text elements total.\n- Stagger reveals rather than showing everything at once — give each element room to breathe.\n- Prefer slow, deliberate timing — entrances at 20-25 frames feel confident, rushed animations at 8-10 frames feel cheap.\n- Leave generous hold time between sections — do not animate continuously from frame 0 to the end.\n- Never stack more than three animation layers deep — avoid wrapping FadeIn inside SlideIn inside ScaleIn.\n- ** One dominant visual element per animation — a single Counter, a single heading, a single logo. Supporting elements should feel secondary.**\n- Prefer a single focal point centered on the canvas over busy multi-column layouts.\n- Whitespace is intentional — a centered heading with room around it reads better than content filling the full canvas.`;\n\"#\n\ntemplate_string CodeGenerationRules() #\"\n## RULES:\n\nThe following rules are strict and must always be followed when generating the component.\n\n## Component contract\n- Component receives no props — export as: export default function RemoteComponent() { ... }\n- Never import from \"remotion\" or any other library.\n- Never use useCurrentFrame, interpolate, spring, or any Remotion hook directly.\n\n## Layout\n- SafeArea must always be the outermost wrapper. Nothing renders outside it.\n- Every visible element must be a direct child of Stack, Row, or AbsoluteCenter — never place components as siblings without a layout primitive.\n- Use Stack for vertical arrangement, Row for horizontal. Nest them for complex layouts.\n- Never use position:absolute, position:fixed, or position:relative — AbsoluteCenter is the only component that handles absolute positioning.\n- Never create wrapper divs purely for layout — use Stack and Row instead.\n- Never animate an empty div — every animation primitive must wrap visible content.\n- Plain React divs are allowed only for geometric shapes and decorative elements (circles, dividers, lines). Never for layout.\n- Spacing values for gap, padding, margin must be token values only mentioned above\n\n## Styling\n- Never set color, fontSize, fontWeight, letterSpacing, or fontFamily in style props — the design system controls these automatically.\n- Never hardcode hex colors or rgba color values.\n- Never hardcode font sizes — use Text variant prop instead.\n- style props are for geometry and layout only: width, height, maxWidth, borderRadius, overflow, padding, margin.\n\n## Animation\n- Never use JSX conditionals for animated elements — use TimelineGate instead.\n- Never animate an empty or invisible element.\n- Always wrap content in an animation primitive to animate it — content primitives (Text, Counter, LogoAsset) never animate themselves.\n- Width and height on LogoAsset define its bounding box; the logo remains contained without distortion.\n\n## Safety\n- Only use primitives, layout components from the AVAILABLE list. Never invent new component names.\n- Never use className for layout or styling — it is not supported in the animation runtime.\n\"#\n\ntemplate_string AllComponentsList() #\"\n## AVAILABLE VISUAL MECHANISMS\n\nUse only these when designing your concept. Do not invent mechanisms that don't exist.\n\n### Entrances\nFadeIn, SlideIn, ScaleIn — reveal elements onto the canvas\n\n### Exits\nFadeOut, SlideOut, ScaleOut — remove elements from the canvas\n\n### Sequencing\nStagger — reveal a list of items one after another\nTimelineGate — show or hide a section at a specific moment\n\n### Text\nText — static label or heading\nTypewriter — text that types itself out progressively\nWordCycle — a word that cycles through multiple values\n\n### Numbers\nCounter — a number that animates up or down to a target value\n\n### Layout\nStack — vertical arrangement\nRow — horizontal arrangement\nAbsoluteCenter — center content on the canvas\n\n### Brand\nLogoAsset — the brand logo\n\n### Pre-built\nTitleCard — a full hero title composition with heading and subheading\n\"#\n\ntemplate_string FrameDurationRules() #\"\n## FRAME DURATION RULES\n\n**All timing values are in frames (fps=30).**\nNever use decimal values for duration or startAt.\nAlways use whole numbers: durationInFrames={20} not durationInFrames={0.7}\n\nBuild the timeline element by element. Each element's startAt is:\n  startAt = previous element's (startAt + duration) + hold\n\nDefault hold between elements: 6 frames\nHold between sections (topic changes): 15 frames\nHold at end after last element: 20 frames minimum\n\n## Sequential example\n\nLogo fades in\n  startAt=0  duration=20  ends=20\n\nHeading slides in (6 frame hold)\n  startAt=26  duration=20  ends=46\n\nSubheading fades in (6 frame hold)\n  startAt=52  duration=20  ends=72\n\n## Elements that form one visual unit — start together\n\nCounter and its label    → same startAt\nHeading and eyebrow      → same startAt\nLogo and company name    → same startAt\n\n## Stagger end frame\n\nlast child ends at: startAt + ((childCount - 1) × delayBetween) + childDuration\nnext element startAt = stagger end frame + hold\n\n## Typewriter duration\n\nchar mode:  durationInFrames = text.length × 2\nword mode:  durationInFrames = wordCount × 10\nnext element startAt = Typewriter startAt + durationInFrames + hold\n\n## Total duration targets\nNever exceed 240 frames for a single slide.\n\"#",
	"common_prompts.baml":             "template_string BrandGuidelines(resume: VideoBranding) #\"\n    {% if resume.brandGuideLines %}\n    ### Brand Details:\n    {{ resume.brandGuideLines }}\n    {% endif %}\n\"#\n\ntemplate_string AnimationTypes() #\"\n    ## Available Animation types\n    BRAND = Used for brand-led moments such as logo reveals, identity motion, or signature visual language.\n    TEXT = kinetic text, typewriter effects, text animations, word carousels, animated titles, text-heavy content slide with icons, sections etc. Used for strong statements, hooks, quotes, definitions, or key transitions\n\"#\n\ntemplate_string AllAnimationTypes() #\"\n    ## Available Animation types\n    BRAND = Used for brand-led moments such as logo reveals, identity motion, or signature visual language.\n    PRODUCT = Used when showcasing real-world tools or interfaces like Slack, WhatsApp, CRM systems, dashboards, or any software relevant to the narrative. Helps ground the story in practical, relatable workflows\n    TEXT = kinetic text, typewriter effects, text animations, word carousels, animated titles, text-heavy content slide with icons, sections etc. Used for strong statements, hooks, quotes, definitions, or key transitions\n    VISUAL = Purely visual animated slide (icons, illustrations, motion graphics, abstract visuals). Minimal text\n    STATS = Animated numerical highlights such as metrics, percentages, counters, growth numbers, comparisons\n    CHART = Data visualization slide such as data visualizations, graphs, histograms, bar charts, pie charts, progress bars, statistics, metrics\n    SIMPLE_TEXT= Used when you need to show a short 1–2 line message without heavy animation. Ideal for pauses, emphasis, or clean statements\n\"#\n\ntemplate_string AskQuestionGuidelines() #\"\n    ### Question Guidelines\n    Questions must:\n    * Be asked **only when critical information is missing**\n    * Be **max 8-15 words**\n    * Include **2–3 options**\n    * Always guide visual direction\n    * Avoid open-ended questions\n\"#\n",
	"edit_animation.baml":             "enum AnimationCodeEditType {\n  TARGETED_EDITS @description(\"\")\n  FULL_REWRITE @description(\"\")\n}\n\nclass EditAnimationCodeRequest {\n  code string\n  prompt string\n}\n\nclass EditAnimationCodeResponse {\n  type AnimationCodeEditType\n  edits EditString[]\n}\n\nclass EditString {\n  description string @description(\"Brief description of this edit\")\n  oldString string @description(\"The exact string to find (must match exactly, including whitespace)\")\n  newString string @description(\"The replacement string\")\n}\n\nfunction EditAnimationCode(resume: EditAnimationCodeRequest, conversation_history: Message[]) -> EditAnimationCodeResponse {\n  client CustomOpenAI5\n  prompt #\"\n    You are an expert at making targeted edits to React components.\n\n    Given the current code and a user request, decide whether to:\n    1. Use targeted edits (for small, specific changes)\n    2. Provide full replacement code (for major restructuring)\n\n    ## WHEN TO USE TARGETED EDITS (type: TARGETED_EDITS)\n    - Changing colors, text, numbers, timing values\n    - Adding or removing a single element\n    - Modifying styles or properties\n    - Small additions (new variable, new element)\n    - Changes affecting <30% of the code\n\n    ## WHEN TO USE FULL REPLACEMENT (type: FULL_REWRITE)\n    - Completely different animation style\n    - Major structural reorganization\n    - User asks to \"start fresh\" or \"rewrite\"\n    - Changes affect >50% of the code\n\n    ## EDIT FORMAT\n    For targeted edits, each edit needs:\n    - old_string: The EXACT string to find (including whitespace/indentation)\n    - new_string: The replacement string\n\n    CRITICAL:\n    - old_string must match the code EXACTLY character-for-character\n    - Include enough surrounding context to make old_string unique\n    - If multiple similar lines exist, include more surrounding code\n    - Preserve indentation exactly as it appears in the original\n\n    --------------------------------------------------\n    INPUT\n    --------------------------------------------------\n\n    ## CURRENT CODE\n    {{ resume.code }}\n\n    ## USER REQUEST:\n    {{ resume.prompt }}\n\n    --------------------------------------------------\n\n    {% if conversation_history %}\n    ## Conversation History\n    {% for message in conversation_history %}\n    {{ _.role(message.role) }} {{ message.content }}\n    {% endfor %}\n    {% endif %}\n\n    {{ ctx.output_format }}\n\n  \"#\n}",
	"extract_template_config.baml":    "class TemplateConfigExtractorInput {\n  schema string\n  beatDescription string\n  templateDescription string\n  branding VideoBranding\n}\n\nclass TemplateConfigExtractorOutput {\n  config string\n    @description(\"Strictly valid JSON object that fully conforms to the provided schema. Must not contain explanations, comments, or extra fields.\")\n}\n\nfunction ExtractTemplateConfig(input: TemplateConfigExtractorInput) -> TemplateConfigExtractorOutput {\n  client CustomOpenAI5\n  prompt #\"\n  ```markdown\n  # Template Configuration Generator (Strict Mode)\n  You are a strict JSON configuration generator.\n\n  Your task is to transform a **beat description** into a **valid configuration object** for a given template.\n\n  The output must:\n  - EXACTLY conform to the provided JSON schema\n  - Contain ONLY fields defined in the schema\n  - Be fully valid, parseable JSON\n  - Contain NO explanations or extra text\n\n  ---\n\n  ## Definitions\n\n  **Beat Description**\n  Describes the narrative intent of the slide — what is happening, what message is conveyed, and what should be emphasized.\n\n  **Template Description**\n  Describes how the template behaves — including layout, animation logic, supported fields, and how configuration values affect rendering.\n\n  ---\n\n  ## Input\n\n  **Schema:**\n  ```\n\n  {{ input.schema }}\n\n  ```\n\n  **Beat Description:**\n  ```\n\n  {{ input.beatDescription }}\n\n  ```\n\n  **Template Description(how the template looks like in behavior):**\n  ```\n\n  {{ input.templateDescription }}\n\n  ```\n\n  {{ BrandGuidelines(input.branding) }}\n\n  ---\n\n  ## Generation Strategy (IMPORTANT)\n\n  Follow this exact order:\n\n  1. **Understand the template first**\n     - Identify what each schema field represents visually or behaviorally\n     - Use templateDescription as the primary source of truth\n\n  2. **Extract intent from the beat**\n     - Identify key message, tone, emphasis, and content elements\n     - Ignore irrelevant narrative details\n\n  3. **Map beat → schema fields**\n     - Every field must be populated using:\n       - Direct content from beatDescription, OR\n       - Logical inference based on templateDescription\n\n  4. **Resolve ambiguity**\n     - If the beat does not specify a value:\n       - Use reasonable defaults consistent with template behavior\n       - Do NOT invent unrelated content\n\n  5. **Respect constraints strictly**\n     - Follow types, enums, required fields, nesting, and array structures exactly\n\n  ---\n\n  ## 🔹 Hard Rules\n\n  1. Do NOT add fields not in the schema\n  2. Do NOT omit required fields\n  3. Do NOT change field names\n  4. Do NOT output null unless schema allows it\n  5. Do NOT include placeholder text like \"TBD\"\n  6. Keep values concise and presentation-ready\n  7. Ensure output aligns with BOTH:\n     - beatDescription (content)\n     - templateDescription (behavior)\n\n  ---\n\n  ## Output Rules (Strict)\n\n  - Output ONLY a JSON object\n  - No markdown\n  - No backticks\n  - No comments\n  - No explanations\n  - No trailing commas\n  - Must be valid JSON\n  ```\n\n  --------------------------------------------------\n  OUTPUT FORMAT\n  --------------------------------------------------\n\n  {{ ctx.output_format }}\n  \"#\n}\n\n",
	"generators.baml":                 "// This helps use auto generate libraries you can use in the language of\n// your choice. You can have multiple generators if you use multiple languages.\n// Just ensure that the output_dir is different for each generator.\ngenerator target {\n    // Valid values: \"python/pydantic\", \"typescript\", \"go\", \"rust\", \"ruby/sorbet\", \"rest/openapi\"\n    output_type \"go\"\n\n    // Where the generated code will be saved (relative to baml_src/)\n    output_dir \"../\"\n\n    // The version of the BAML package you have installed (e.g. same version as your baml-py or @boundaryml/baml).\n    // The BAML VSCode extension version should also match this version.\n    version \"0.218.1\"\n\n    // 'baml-cli generate' will run this after generating go code\n    // This command will be run from within $output_dir/baml_client\n    on_generate \"gofmt -w . && goimports -w .\"\n\n    // Your Go packages name as specified in go.mod\n    // We need this to generate correct imports in the generated baml_client\n    client_package_name \"github.com/shank318/coasterai\"\n}\n",
	"match_categories.baml":           "class Category {\n  name string\n  description string @description(\"Clear explanation of the conceptual animation category. Describes the idea or scenario this category represents (e.g., data fragmentation, growth acceleration, workflow automation, before vs after transformation). Not a visual style.\")\n}\n\nclass MatchCategoriesRequest {\n  categories Category[] @description(\"Predefined conceptual animation categories to choose from. You must select only from this list.\")\n  query string @description(\"Concept or idea that needs to be mapped to the most relevant conceptual animation category.\")\n}\n\nclass MatchCategoriesResponse {\n  categories Category[] @description(\"matched category based on the query, return empty if no match found\")\n}\n\nfunction MatchCategories(resume: MatchCategoriesRequest) -> MatchCategoriesResponse {\n  // Specify a client as provider/model-name\n  // You can also use custom LLM params with a custom client name from clients.baml like \"client CustomGPT5\" or \"client CustomSonnet4\"\n  client CustomOpenAI5\n  prompt #\"\n  Category Matching Engine\n\n  You are a strict semantic classification engine.\n\n  Your task is to match the given query to one or more predefined conceptual categories.\n\n  You must ONLY select from the provided categories.\n  You must NEVER invent new categories.\n  You must NEVER modify category names or descriptions.\n\n  --------------------------------------------------\n  INPUT\n  --------------------------------------------------\n\n  Query:\n  {{ resume.query }}\n\n  Available Categories:\n  {% for category in resume.categories %}\n  - {{ category.name }}:\n    {{ category.description }}\n  {% endfor %}\n\n  --------------------------------------------------\n  MATCHING RULES\n  --------------------------------------------------\n\n  1. Understand the core concept expressed in the query.\n  2. Compare it against category descriptions.\n  3. Select categories that clearly represent the same conceptual idea.\n  4. Exclude categories that:\n     - Only partially match\n     - Are loosely related\n     - Represent visual style instead of concept\n     - Do not strongly align with the core idea\n\n  Be conservative:\n  If the match is unclear or weak, return an empty list.\n\n  If multiple categories clearly match, return them ordered by strongest relevance first.\n\n  --------------------------------------------------\n  IMPORTANT RULES\n  --------------------------------------------------\n\n  - Only return categories from the provided list.\n  - Do NOT create new categories.\n  - Do NOT explain reasoning.\n  - Do NOT include thinking.\n  - If none clearly match, return an empty array.\n\n  --------------------------------------------------\n  OUTPUT FORMAT\n  --------------------------------------------------\n\n  {{ ctx.output_format }}\n  \"#\n}",
	"match_templates.baml":            "class TemplateItem {\n  name string\n  description string @description(\"Clear explanation of what this template visually communicates\")\n}\n\nclass MatchTemplateRequest {\n  currentBeat string @description(\"Narrative intent of the slide being generated\")\n  planSoFar Section[] @description(\"Only the sections and slides that have already been generated\")\n  templates TemplateItem[] @description(\"Templates available for the NEXT slide\")\n}\n\nclass MatchTemplateResponse {\n  templates TemplateItem[] @description(\"Templates that best continue the narrative progression\")\n}\n\nfunction MatchTemplate(resume: MatchTemplateRequest) -> MatchTemplateResponse {\n  client CustomOpenAI5\n  prompt #\"\n    ## Narrative Template Continuation Engine\n\n    You are a visual storytelling progression engine.\n\n    Your role is NOT to match keywords.\n    Your role is to decide:\n\n    👉 What visual structure best continues the story from what has already been shown.\n\n    You must evaluate:\n\n    1. What narrative stage has already been covered\n    2. What emotional / logical progression exists\n    3. What the NEXT beat intends to communicate\n\n    Then select ONLY templates that best VISUALLY continue the journey.\n\n    You are choosing:\n    NOT what fits the slide\n    BUT what moves the story forward.\n\n    --------------------------------------------------\n    EVALUATION LOGIC\n    --------------------------------------------------\n\n    Step 1: Understand narrative so far\n    - What has been introduced?\n    - What has been explained?\n    - What has been emphasized?\n\n    Step 2: Understand the next beat\n    - Is it escalation?\n    - Clarification?\n    - Contrast?\n    - Proof?\n    - Resolution?\n\n    Step 3: Choose templates that:\n    ✔ Extend progression\n    ✔ Add structural value\n    ✔ Maintain tone continuity\n    ✔ Improve clarity or persuasion\n\n    REMOVE templates that:\n    ✘ Repeat what has already been shown\n    ✘ Introduce visual regression\n    ✘ Break narrative flow\n    ✘ Add decorative but non-structural value\n\n    Be strict.\n    If unsure → return empty.\n\n    --------------------------------------------------\n    OUTPUT RULES\n    --------------------------------------------------\n\n    - Return ONLY from provided templates\n    - Do NOT modify templates\n    - Order by strongest continuation fit\n    - If none clearly progress the story → return empty\n\n    --------------------------------------------------\n    INPUT\n    --------------------------------------------------\n\n    ## Narrative So Far\n\n    {% for section in resume.planSoFar %}\n      {% if section.slides|length > 0 %}\n    Section: {{ section.name }}\n        {% for slide in section.slides %}\n    - Concept: {{ slide.beatDescription }}\n      Visual: {{ slide.selectedTemplateDescription }}\n        {% endfor %}\n      {% endif %}\n    {% endfor %}\n\n    ## Next Beat To Visualize\n\n    {{ resume.currentBeat }}\n\n    ## Available Visual templates to choose from\n\n    {% for template in resume.templates %}\n    - {{ template.name }}:\n      {{ template.description }}\n    {% endfor %}\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n",
	"regenerate_animation_code.baml":  "class ReGenerateAnimationCodeRequest {\n  code string\n  animationType AnimationType\n  prompt string\n  durationInFrames int\n  branding VideoBranding\n}\n\nclass ReGenerateAnimationCodeResponse {\n  code string @description(\"Typescript code\")\n}\n\nfunction ReGenerateAnimation(resume: ReGenerateAnimationCodeRequest, conversation_history: Message[]) -> ReGenerateAnimationCodeResponse {\n  client CustomOpenAI5\n  prompt #\"\n    You are modifying an existing React animation component for a video slide.\n\n    ---\n\n    ## CONTEXT\n    You will receive the current component code and edit instructions.\n    Your job is to apply the requested changes while preserving everything else.\n\n    The component runs inside a managed animation runtime with strict rules.\n    Any code that violates the rules will be rejected automatically.\n\n    ---\n\n    ## EDITING RULES\n\n    1. Modify the existing code — never rewrite from scratch.\n    2. Only change what the edit instructions require. Leave everything else untouched.\n    3. Never rename the exported component.\n    4. Never remove animation logic unless the edit explicitly requires it.\n    5. When adding elements, integrate them into the existing layout naturally.\n    6. Keep all existing timing values unless the edit changes them.\n    7. All rules from the generation prompt apply here too — no hex colors, no arbitrary px, no Remotion imports, style props for layout only.\n\n    ---\n\n    {{ CodeGeneration() }}\n    {{ CodeGenerationMustHave() }}\n    {{ FrameDurationRules() }}\n    ---\n\n    ## INPUT\n\n    Resolution and Canvas Size:\n    16x9(1920x1080)\n\n   {{ BrandGuidelines(resume.branding) }}\n\n    Animation Duration In Frames:\n    {{ resume.duration }}\n\n    ## Requested Edits\n    {{ resume.prompt }}\n\n    ## Existing Animation Code\n    {{ resume.code }}\n\n    ---\n\n    {% if conversation_history %}\n    ## Conversation History\n    {% for message in conversation_history %}\n    {{ _.role(message.role) }} {{ message.content }}\n    {% endfor %}\n    {% endif %}\n\n    ---\n    {{ ctx.output_format }}\n  \"#\n}",
	"remotion_skills.baml":            "template_string RemotionSkillChart() ##\"\n{% raw %}\n---\nname: charts\ndescription: Chart and data visualization patterns for Remotion. Use when creating bar charts, pie charts, line charts, stock graphs, or any data-driven animations.\nmetadata:\n  tags: charts, data, visualization, bar-chart, pie-chart, line-chart, stock-chart, svg-paths, graphs\n---\n\n# Charts in Remotion\n\nCreate charts using React code - HTML, and SVG are all supported.\n\nDisable all animations from third party libraries - they cause flickering.\nDrive all animations from `useCurrentFrame()`.\n\n## Bar Chart\n\n```tsx\nconst STAGGER_DELAY = 5;\nconst frame = useCurrentFrame();\nconst { fps } = useVideoConfig();\n\nconst bars = data.map((item, i) => {\n  const height = spring({\n    frame,\n    fps,\n    delay: i * STAGGER_DELAY,\n    config: { damping: 200 },\n  });\n  return <div style={{ height: height * item.value }} />;\n});\n```\n\n## Pie Chart\n\nAnimate segments using stroke-dashoffset, starting from 12 o'clock:\n\n```tsx\nconst progress = interpolate(frame, [0, 100], [0, 1]);\nconst circumference = 2 * Math.PI * radius;\nconst segmentLength = (value / total) * circumference;\nconst offset = interpolate(progress, [0, 1], [segmentLength, 0]);\n\n<circle\n  r={radius}\n  cx={center}\n  cy={center}\n  fill=\"none\"\n  stroke={color}\n  strokeWidth={strokeWidth}\n  strokeDasharray={`${segmentLength} ${circumference}`}\n  strokeDashoffset={offset}\n  transform={`rotate(-90 ${center} ${center})`}\n/>;\n```\n\n## Line Chart / Path Animation\n\nUse `@remotion/paths` for animating SVG paths (line charts, stock graphs, signatures).\n\n### Convert data points to SVG path\n\n```tsx\ntype Point = { x: number; y: number };\n\nconst generateLinePath = (points: Point[]): string => {\n  if (points.length < 2) return \"\";\n  return points.map((p, i) => `${i === 0 ? \"M\" : \"L\"} ${p.x} ${p.y}`).join(\" \");\n};\n```\n\n### Draw path with animation\n\n```tsx\nimport { evolvePath } from \"@remotion/paths\";\n\nconst path = \"M 100 200 L 200 150 L 300 180 L 400 100\";\nconst progress = interpolate(frame, [0, 2 * fps], [0, 1], {\n  extrapolateLeft: \"clamp\",\n  extrapolateRight: \"clamp\",\n  easing: Easing.out(Easing.quad),\n});\n\nconst { strokeDasharray, strokeDashoffset } = evolvePath(progress, path);\n\n<path\n  d={path}\n  fill=\"none\"\n  stroke=\"#FF3232\"\n  strokeWidth={4}\n  strokeDasharray={strokeDasharray}\n  strokeDashoffset={strokeDashoffset}\n/>;\n```\n\n### Follow path with marker/arrow\n\n```tsx\nimport {\n  getLength,\n  getPointAtLength,\n  getTangentAtLength,\n} from \"@remotion/paths\";\nconst pathLength = getLength(path);\nconst point = getPointAtLength(path, progress * pathLength);\nconst tangent = getTangentAtLength(path, progress * pathLength);\nconst angle = Math.atan2(tangent.y, tangent.x);\n<g\n  style={{\n    transform: `translate(${point.x}px, ${point.y}px) rotate(${angle}rad)`,\n    transformOrigin: \"0 0\",\n  }}\n>\n  <polygon points=\"0,0 -20,-10 -20,10\" fill=\"#FF3232\" />\n</g>;\n{% endraw %}\n\"##\n\ntemplate_string RemotionSkillMeasureDOMNode() #\"\n{% raw %}\n---\nname: measuring-dom-nodes\ndescription: Measuring DOM element dimensions in Remotion\nmetadata:\n  tags: measure, layout, dimensions, getBoundingClientRect, scale\n---\n\n# Measuring DOM nodes in Remotion\n\nRemotion applies a `scale()` transform to the video container, which affects values from `getBoundingClientRect()`. Use `useCurrentScale()` to get correct measurements.\n\n## Measuring element dimensions\n\n```tsx\nimport { useCurrentScale } from \"remotion\";\nimport { useRef, useEffect, useState } from \"react\";\n\nexport const MyComponent = () => {\n  const ref = useRef<HTMLDivElement>(null);\n  const scale = useCurrentScale();\n  const [dimensions, setDimensions] = useState({ width: 0, height: 0 });\n\n  useEffect(() => {\n    if (!ref.current) return;\n    const rect = ref.current.getBoundingClientRect();\n    setDimensions({\n      width: rect.width / scale,\n      height: rect.height / scale,\n    });\n  }, [scale]);\n\n  return <div ref={ref}>Content to measure</div>;\n};\n```\n{% endraw %}\n\"#\n\ntemplate_string RemotionSkillMeasureText() #\"\n{% raw %}\n---\nname: measuring-text\ndescription: Measuring text dimensions, fitting text to containers, and checking overflow\nmetadata:\n  tags: measure, text, layout, dimensions, fitText, fillTextBox\n---\n\n# Measuring text in Remotion\n```\n\n## Measuring text dimensions\n\nUse `measureText()` to calculate the width and height of text:\n\n```tsx\nimport { measureText } from \"@remotion/layout-utils\";\n\nconst { width, height } = measureText({\n  text: \"Hello World\",\n  fontFamily: \"Arial\",\n  fontSize: 32,\n  fontWeight: \"bold\",\n});\n```\n\nResults are cached - duplicate calls return the cached result.\n\n## Fitting text to a width\n\nUse `fitText()` to find the optimal font size for a container:\n\n```tsx\nimport { fitText } from \"@remotion/layout-utils\";\nconst { fontSize } = fitText({\n  text: \"Hello World\",\n  withinWidth: 600,\n  fontFamily: \"Inter\",\n  fontWeight: \"bold\",\n});\nreturn (\n  <div\n    style={{\n      fontSize: Math.min(fontSize, 80), // Cap at 80px\n      fontFamily: \"Inter\",\n      fontWeight: \"bold\",\n    }}\n  >\n    Hello World\n  </div>\n);\n\n## Checking text overflow\n\nUse `fillTextBox()` to check if text exceeds a box:\n\n```tsx\nimport { fillTextBox } from \"@remotion/layout-utils\";\n\nconst box = fillTextBox({ maxBoxWidth: 400, maxLines: 3 });\n\nconst words = [\"Hello\", \"World\", \"This\", \"is\", \"a\", \"test\"];\nfor (const word of words) {\n  const { exceedsBox } = box.add({\n    text: word + \" \",\n    fontFamily: \"Arial\",\n    fontSize: 24,\n  });\n  if (exceedsBox) {\n    // Text would overflow, handle accordingly\n    break;\n  }\n}\n```\n\n## Best practices\n\n**Load fonts first:** Only call measurement functions after fonts are loaded.\n\n```tsx\nimport { loadFont } from \"@remotion/google-fonts/Inter\";\n\nconst { fontFamily, waitUntilDone } = loadFont(\"normal\", {\n  weights: [\"400\"],\n  subsets: [\"latin\"],\n});\n\nwaitUntilDone().then(() => {\n  // Now safe to measure\n  const { width } = measureText({\n    text: \"Hello\",\n    fontFamily,\n    fontSize: 32,\n  });\n});\n```\n\n**Use validateFontIsLoaded:** Catch font loading issues early:\n\n```tsx\nmeasureText({\n  text: \"Hello\",\n  fontFamily: \"MyCustomFont\",\n  fontSize: 32,\n  validateFontIsLoaded: true, // Throws if font not loaded\n});\n```\n\n**Match font properties:** Use the same properties for measurement and rendering:\n\n```tsx\nconst fontStyle = {\n  fontFamily: \"Inter\",\n  fontSize: 32,\n  fontWeight: \"bold\" as const,\n  letterSpacing: \"0.5px\",\n};\n\nconst { width } = measureText({\n  text: \"Hello\",\n  ...fontStyle,\n});\n\nreturn <div style={fontStyle}>Hello</div>;\n```\n\n**Avoid padding and border:** Use `outline` instead of `border` to prevent layout differences:\n\n```tsx\n<div style={{ outline: \"2px solid red\" }}>Text</div>\n```\n{% endraw %}\n\"#\n\ntemplate_string RemotionSkillSequencing() #\"\n{% raw %}\n---\nname: sequencing\ndescription: Sequencing patterns for Remotion - delay, trim, limit duration of items\nmetadata:\n  tags: sequence, series, timing, delay, trim\n---\n\nUse `<Sequence>` to delay when an element appears in the timeline.\n\n```tsx\nimport { Sequence } from \"remotion\";\n\nconst {fps} = useVideoConfig();\n\n<Sequence from={1 * fps} durationInFrames={2 * fps} premountFor={1 * fps}>\n  <Title />\n</Sequence>\n<Sequence from={2 * fps} durationInFrames={2 * fps} premountFor={1 * fps}>\n  <Subtitle />\n</Sequence>\n```\n\nThis will by default wrap the component in an absolute fill element.\nIf the items should not be wrapped, use the `layout` prop:\n\n```tsx\n<Sequence layout=\"none\">\n  <Title />\n</Sequence>\n```\n\n## Premounting\n\nThis loads the component in the timeline before it is actually played.\nAlways premount any `<Sequence>`!\n\n```tsx\n<Sequence premountFor={1 * fps}>\n  <Title />\n</Sequence>\n```\n\n## Series\n\nUse `<Series>` when elements should play one after another without overlap.\n\n```tsx\nimport { Series } from \"remotion\";\n\n<Series>\n  <Series.Sequence durationInFrames={45}>\n    <Intro />\n  </Series.Sequence>\n  <Series.Sequence durationInFrames={60}>\n    <MainContent />\n  </Series.Sequence>\n  <Series.Sequence durationInFrames={30}>\n    <Outro />\n  </Series.Sequence>\n</Series>;\n```\n\nSame as with `<Sequence>`, the items will be wrapped in an absolute fill element by default when using `<Series.Sequence>`, unless the `layout` prop is set to `none`.\n\n### Series with overlaps\n\nUse negative offset for overlapping sequences:\n\n```tsx\n<Series>\n  <Series.Sequence durationInFrames={60}>\n    <SceneA />\n  </Series.Sequence>\n  <Series.Sequence offset={-15} durationInFrames={60}>\n    {/* Starts 15 frames before SceneA ends */}\n    <SceneB />\n  </Series.Sequence>\n</Series>\n```\n\n## Frame References Inside Sequences\n\nInside a Sequence, `useCurrentFrame()` returns the local frame (starting from 0):\n\n```tsx\n<Sequence from={60} durationInFrames={30}>\n  <MyComponent />\n  {/* Inside MyComponent, useCurrentFrame() returns 0-29, not 60-89 */}\n</Sequence>\n```\n\n## Nested Sequences\n\nSequences can be nested for complex timing:\n\n```tsx\n<Sequence from={0} durationInFrames={120}>\n  <Background />\n  <Sequence from={15} durationInFrames={90} layout=\"none\">\n    <Title />\n  </Sequence>\n  <Sequence from={45} durationInFrames={60} layout=\"none\">\n    <Subtitle />\n  </Sequence>\n</Sequence>\n```\n\n## Nesting compositions within another\n\nTo add a composition within another composition, you can use the `<Sequence>` component with a `width` and `height` prop to specify the size of the composition.\n\n```tsx\n<AbsoluteFill>\n  <Sequence width={COMPOSITION_WIDTH} height={COMPOSITION_HEIGHT}>\n    <CompositionComponent />\n  </Sequence>\n</AbsoluteFill>\n```\n{% endraw %}\n\"#",
	"slide_planner.baml":              "enum AnimationType {\n  BRAND @description(\"Used for brand-led moments such as logo reveals, identity motion, or signature visual language. Typically placed at the beginning, end, or both to establish and reinforce brand recall.\")\n  // PRODUCT @description(\"Used when showcasing real-world tools or interfaces like Slack, WhatsApp, CRM systems, dashboards, or any software relevant to the narrative. Helps ground the story in practical, relatable workflows.\")\n  TEXT @description(\"kinetic text, typewriter effects, text animations, word carousels, animated titles, text-heavy content slide. Used for strong statements, hooks, quotes, definitions, or key transitions.\")\n  // VISUAL @description(\"Purely visual animated slide (icons, illustrations, motion graphics, abstract visuals). Minimal text.\")\n  // STATS @description(\"Animated numerical highlights such as metrics, percentages, counters, growth numbers, comparisons.\")\n  // CHART @description(\"Data visualization slide such as data visualizations, graphs, histograms, bar charts, pie charts, progress bars, statistics, metrics.\")\n  SIMPLE_TEXT @description(\"Used when you need to show a short 1–2 line message without heavy animation. Ideal for pauses, emphasis, or clean statements.\")\n}\n\nclass AnimationSlide {\n  index int\n    @description(\"Sequential order of the slide inside its section (starts from 1).\")\n\n  beatDescription string\n    @description(\"Narrative purpose of this slide. Describe what happens in this moment of the video and how it connects to previous and next slides.\")\n\n  animationType AnimationType\n    @description(\"Type of animation to use based on the storytelling need.\")\n\n  categorySearchQuery string\n    @description(\"Semantic search query describing the conceptual animation category, NOT visual style. This should capture the core idea being represented (e.g. 'data fragmentation problem', 'centralization of scattered systems', 'growth acceleration', 'workflow automation'). The query maps to conceptual animation categories, not design aesthetics.\")\n\n  duration int\n    @description(\"Duration in seconds. Average 4-8s per slide Keep pacing dynamic. Avoid repetitive durations.\")\n\n  voiceover string? @description(\"voiceover to play at this slide, if you think its good to add\")\n\n  selectedTemplateDescription string? @skip()\n}\n\nclass MediaSlide {\n  index int\n    @description(\"Sequential order of the slide inside its section (starts from 1).\")\n\n  beatDescription string\n    @description(\"Clear instruction for what media to include (product demo, UI screenshot, testimonial clip, stock footage, founder image, etc). Must explain why this media is shown at this point in the story.\")\n\n  duration int\n    @description(\"Duration in seconds. Should support narrative pacing.\")\n\n  selectedTemplateDescription string? @skip()\n}\n\nclass ScriptItem {\n name string\n voiceover string?\n reference string?\n}\n\nclass VideoGenerationPlanRequest {\n    Duration int\n    Prompt string\n    Language string\n    Resolution string\n    Script  ScriptItem[]\n    VideoBranding VideoBranding\n    BrandLibraryID string? @skip // Just needed to store the request as it is\n    AvailableAnimationTypes AnimationType[]\n}\n\nclass VideoGenerationPlan {\n    videoName string @description(\"name of the video, around 5 to 15 length\")\n    sections Section[]\n}\n\nclass Section {\n  name string @description(\"name of the section, around one or two words\")\n  slides (AnimationSlide | MediaSlide)[]\n}\n\nclass VideoBranding {\n  brandGuideLines string? @skip @description(\"user provided brand guidelines\")\n}\n\nclass StreamingVideoGenerationPlan {\n  plan (VideoGenerationPlan | AskUserQuestion) @description(\"Either the final video generation plan or a question for the user\")\n}\n\nclass Message {\n  role \"user\" | \"assistant\" | \"tool\"\n  content string\n  tool_call_id string? @description(\"ID for tool calls and responses\")\n}\n\nclass AskUserQuestion {\n  tool_name \"ask_user_question\" @description(\"Use this tool to ask the user a question when you need clarification or additional information\")\n  question_text string @description(\"The question to ask the user. Keep it concise (8 words or less).\")\n  options string[] @description(\"The answer choices for the user to select from\")\n  allow_custom_entry bool? @description(\"Whether to allow custom text entry in addition to the predefined options\")\n}\n\nfunction GeneratePlanStreaming(input: VideoGenerationPlanRequest, conversation_history: Message[]) -> StreamingVideoGenerationPlan {\n  client CustomOpenAI5\n  prompt #\"\n    You are a cinematic video planning director.\n\n    Your job is to transform a user's idea or script into a coherent, story-driven slide plan using:\n    - AnimationSlides (concept-driven motion graphics)\n    - MediaSlides (real product visuals, screenshots, images, demo clips, testimonials)\n\n    The output must feel like a real edited video — not a list of slides.\n\n    # CORE RULES\n    ## 1. Script Priority (MANDATORY)\n    If Script is provided:\n    - Strictly follow it.\n    - Each ScriptItem must map to one or more slides.\n    - Do NOT skip or ignore script items.\n    - Maintain logical order.\n    - Use the voiceover to understand the context\n    - You may expand a script item into multiple slides.\n    - You may add additional sections only if necessary for flow.\n\n    If Script is missing or unclear, use this structure:\n    Hook\n    Problem\n    Insight\n    Product Value\n    Outcome\n    Proof\n    CTA\n\n    ---\n\n    ## 2. Narrative Flow\n    Slides must connect in a smooth flow.\n\n    Each beatDescription must explain:\n    - What happens in this moment\n    - Why it follows the previous slide\n    - What it sets up next\n\n    Avoid isolated slides with no transition logic.\n    ---\n\n    ## 3. Animation Category Logic\n    categorySearchQuery must describe the conceptual animation category.\n\n    It represents:\n    - The core idea being visualized\n    - The problem or transformation being shown\n    - The conceptual motion metaphor\n\n    It does NOT describe:\n    - Design style\n    - Typography\n    - Camera movement\n    - Visual aesthetics\n\n    Examples:\n    - \"data fragmentation across multiple systems\"\n    - \"manual repetitive workflow\"\n    - \"before vs after comparison transformation\"\n    - \"growth acceleration curve\"\n    - \"team collaboration across silos\"\n\n    ---\n\n    ## Slide Type Balance Rules\n    When generating slides, follow these constraints:\n    1. Use **AnimationSlides** primarily to explain concepts, frameworks, or abstract ideas.\n    2. Use **MediaSlides** for product demonstrations where the user will upload screenshots or video clips to showcase features.\n    3. Maintain a healthy balance between slide types. Do not overuse any single type.\n    4. Avoid excessive use of **VISUAL-type animations**.\n    5. Voiceovers are optional. Not every slide requires one, but the overall flow must feel smooth and continuous.\n    6. Ensure that **more than 50% of the total slides are MediaSlides** to avoid producing a fully motion-based video.\n    7. Do not place more than **two MediaSlides consecutively**.\n\n    Ensure these constraints are strictly enforced during slide generation.\n\n    ## 6. Sections\n    - Divide video into meaningful narrative phases.\n    - Sections should represent storytelling shifts.\n    - Do not create arbitrary sections.\n\n    ## 7. Animation Slide Repeatability Rules\n     - BRAND: Should not be overused. Use either at start, end, or both. Avoid repeating frequently and do not insert mid-story unless intentional brand recall is needed.\n     - PRODUCT: Not more than once, used only when showcasing different tools, workflows, or steps across the narrative.\n     - TEXT: Can be used multiple times throughout the story for hooks, transitions, and key statements.\n     - SIMPLE_TEXT: Can be used multiple times for short 1–2 line emphasis moments or pauses.\n     - VISUAL: Can be used multiple times to support storytelling through motion, icons, or abstract visuals.\n     - STATS: Can be used once or twice, only needed when highlighting different metrics or numerical insights.\n     - CHART: Can be used once or twice, only when explaining different datasets or comparisons.\n    ---\n\n    ## PLAN\n    You MUST create a plan before starting execution.\n    You perform best when you explicitly outline your reasoning in structured thinking messages.\n    - If the user’s prompt is complex, use the available tools to gather necessary information and create a structured todo list before execution.\n    - Do not begin execution without first forming a clear plan.\n    ---\n\n    # Ask Questions Rules\n    If you do not have clarity on what should appear visually in the **`bearDescription`** of a slide, you must ask a clarifying question before proceeding.\n    Do **not assume** missing creative direction.\n\n    ### When to Ask\n    Ask if:\n    * A **BRAND** slide is appropriate but brand name is unknown\n    * A **PRODUCT** slide is needed but tools/platforms are unknown\n    * A visual depends on user workflow, stack, or positioning\n    * The script implies something specific but lacks clarity\n    * Any key visual storytelling decision is ambiguous\n\n    Example triggers:\n    * Intro/Outro suggests brand presence → ask brand name\n    * Workflow mention → ask which tool (Slack? CRM? WhatsApp? etc)\n    * Metrics mentioned → ask if real or placeholder\n    * Interface implied → ask which platform to visualize\n    ---\n\n    ## INPUT CONTEXT\n\n    Total duration should be close to {{ input.Duration }} seconds.\n    Allowed variance: +/- 10%.\n\n    Language: {{ input.Language }}\n    Resolution: {{ input.Resolution }}\n\n    {{ BrandGuidelines(input.VideoBranding) }}\n\n    ### Prompt:\n    {{ input.Prompt }}\n\n    {% if input.Script %}\n    ### Script Breakdown (STRICTLY FOLLOW)\n    {% for item in input.Script %}\n    - {{ item.name }}:\n      Voiceover: {{ item.voiceover }}\n      {% if item.reference %}\n      Reference: {{ item.reference }}\n      {% endif %}\n    {% endfor %}\n    {% endif %}\n\n\n    {% if input.AvailableAnimationTypes|length > 0 %}\n    ### IMPORTANT: User wants to only have these animations, You must ONLY use these animation types:\n    {% for animType in input.AvailableAnimationTypes %}\n     - {{ animType }}\n    {% endfor %}\n    {% endif %}\n\n\n    ---\n\n    {% if conversation_history %}\n    ## Conversation History\n    {% for message in conversation_history %}\n    {{ _.role(message.role) }} {{ message.content }}\n    {% endfor %}\n    {% endif %}\n\n    {{ ctx.output_format }}\n  \"#\n}",
}

func getBamlFiles() map[string]string {
	return file_map
}
